:root {
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html,body {
  margin: 0;
  min-height: 100%;
  background: #020617;
}

body {
  font-family: system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
}

.app {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: #020617;
  color: #e5e7eb;
  padding: 24px;
}

.layout {
  width: min(100%,980px);
  display: grid;
  grid-template-columns: repeat(2,minmax(0,1fr));
  align-items: start;
  gap: 16px;
}

.column {
  min-width: 0;
  background: #020617;
  border-radius: 16px;
  border: 1px solid #1f2937;
  padding: 16px;
  display: grid;
  gap: 12px;
}

.title {
  margin: 0;
  font-size: 18px;
  font-weight: 700;
}

.subtitle {
  margin: 4px 0 0;
  font-size: 13px;
  color: #9ca3af;
}

.product-list,.cart-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}

.product-card,.cart-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  padding: 10px;
  border-radius: 12px;
  border: 1px solid #1f2937;
  background: #020617;
}

.product-main,.cart-info {
  min-width: 0;
  display: grid;
  gap: 3px;
}

.product-name,.cart-name {
  font-size: 14px;
  font-weight: 600;
  overflow-wrap: anywhere;
}

.product-price {
  font-size: 13px;
  color: #a3e635;
}

.stock-count {
  font-size: 12px;
  color: #94a3b8;
}

.cart-header {
  display: grid;
  gap: 4px;
}

.cart-meta {
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  color: #9ca3af;
}

.unit-price,.line-total,.subtotal,.discount,.grand-total {
  font-variant-numeric: tabular-nums;
}

.times,.equals {
  opacity: .7;
}

.cart-actions {
  display: flex;
  gap: 6px;
}

button {
  border-radius: 999px;
  border: 1px solid #374151;
  background: #020617;
  color: #e5e7eb;
  padding: 7px 12px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}

button:hover:not(:disabled) {
  border-color: #a3e635;
}

button:focus-visible,input:focus-visible {
  outline: 3px solid #facc15;
  outline-offset: 2px;
}

button:disabled {
  cursor: not-allowed;
  opacity: .45;
}

button.ghost {
  background: transparent;
}

button.danger {
  border-color: #f97316;
  color: #f97316;
}

.empty,.cart-status,.promo-feedback,.checkout-status {
  min-height: 18px;
  margin: 0;
  font-size: 13px;
  color: #94a3b8;
}

.cart-status,.promo-feedback,.checkout-status {
  overflow-wrap: anywhere;
}

.promo-form {
  display: grid;
  gap: 7px;
}

.promo-form label {
  font-size: 13px;
  font-weight: 700;
}

.promo-controls {
  display: flex;
  gap: 8px;
}

.promo-input {
  min-width: 0;
  flex: 1;
  border: 1px solid #475569;
  border-radius: 10px;
  background: #0f172a;
  color: #f8fafc;
  padding: 9px 11px;
}

.apply-promo,.checkout-button {
  background: #365314;
  border-color: #65a30d;
  color: #ecfccb;
}

.summary {
  display: grid;
  gap: 6px;
  margin: 0;
  padding: 12px;
  border: 1px solid #1f2937;
  border-radius: 12px;
}

.summary div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
}

.summary dt,.summary dd {
  margin: 0;
}

.summary dt {
  color: #94a3b8;
}

.summary div:last-child {
  font-weight: 800;
}

.discount {
  color: #bef264;
}

.checkout-button {
  width: 100%;
  border-radius: 10px;
  padding: 10px 14px;
}

@media (max-width:760px) {
  .app {
    padding: 14px;
  }

  .layout {
    grid-template-columns: 1fr;
  }

  .product-card,.cart-row {
    align-items: flex-start;
  }

  .cart-row {
    flex-direction: column;
  }

  .cart-actions {
    width: 100%;
    justify-content: flex-end;
    flex-wrap: wrap;
  }
}

@media (max-width:420px) {
  .product-card {
    align-items: stretch;
    flex-direction: column;
  }

  .promo-controls {
    align-items: stretch;
    flex-direction: column;
  }
}
